import{_ as s,h as e,o as a,aa as i}from"./chunks/framework.BsAE-16a.js";const m=JSON.parse('{"title":"SSH 远程连接","description":"","frontmatter":{},"headers":[],"relativePath":"daily-notes/issue-29.md","filePath":"daily-notes/issue-29.md","lastUpdated":null}'),o={name:"daily-notes/issue-29.md"},l=i(`<h1 id="ssh-远程连接" tabindex="-1">SSH 远程连接 <a class="header-anchor" href="#ssh-远程连接" aria-label="Permalink to &quot;SSH 远程连接&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">原文地址</p><p><a href="https://github.com/wild2life/daily-notes/issues/29" target="_blank" rel="noreferrer">SSH 远程连接 | GitHub</a></p></div><p>涵盖了 <strong>SSH 基础操作、工作原理</strong> 以及 ​<strong>Cursor 配置 Remote-SSH 的完整步骤</strong>​</p><h2 id="ssh-连接原理-简要" tabindex="-1">SSH 连接原理（简要） <a class="header-anchor" href="#ssh-连接原理-简要" aria-label="Permalink to &quot;SSH 连接原理（简要）&quot;">​</a></h2><p>SSH（Secure Shell）在不安全网络上建立<strong>加密</strong>的远程命令行通道，核心三步：</p><ol><li><strong>建立加密通道（握手）</strong><ul><li>服务器发送<strong>主机公钥</strong>给客户端（验证身份，防中间人攻击）。</li><li>客户端生成​<strong>会话密钥</strong>​（对称加密），用服务器公钥加密后发送。</li><li>双方使用该会话密钥加密后续所有通信。</li></ul></li><li><strong>用户身份验证</strong><ul><li>密码验证：通过加密通道传输密码。</li><li>公钥验证（推荐）：客户端用<strong>私钥</strong>签名随机数，服务器用预先存放的<strong>公钥</strong>验证。无需传输密码，更安全。</li></ul></li><li><strong>执行命令</strong> 验证通过后，服务器启动 Shell 会话，所有输入输出均通过加密通道传输。</li></ol><blockquote><p>形象比喻：先挖一条“秘密隧道”（加密通道），然后在隧道里出示“证件”（密码或私钥签名），最后安全地远程指挥服务器干活。</p></blockquote><h2 id="cursor-配置-remote-ssh-连接远程服务器" tabindex="-1">Cursor 配置 Remote-SSH 连接远程服务器 <a class="header-anchor" href="#cursor-配置-remote-ssh-连接远程服务器" aria-label="Permalink to &quot;Cursor 配置 Remote-SSH 连接远程服务器&quot;">​</a></h2><h3 id="_1-安装-remote-ssh-插件" tabindex="-1">1. 安装 Remote-SSH 插件 <a class="header-anchor" href="#_1-安装-remote-ssh-插件" aria-label="Permalink to &quot;1. 安装 Remote-SSH 插件&quot;">​</a></h3><h3 id="_2-编辑-ssh-配置文件" tabindex="-1">2. 编辑 SSH 配置文件 <a class="header-anchor" href="#_2-编辑-ssh-配置文件" aria-label="Permalink to &quot;2. 编辑 SSH 配置文件&quot;">​</a></h3><p>本地配置文件路径：<code>~/.ssh/config</code></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>Host 172.30.6.132</span></span>
<span class="line"><span>    HostName 172.30.6.132</span></span>
<span class="line"><span>    User root</span></span>
<span class="line"><span>    IdentityFile ~/.ssh/id_rsa</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_3-将公钥发给运维开通权限" tabindex="-1">3. 将公钥发给运维开通权限 <a class="header-anchor" href="#_3-将公钥发给运维开通权限" aria-label="Permalink to &quot;3. 将公钥发给运维开通权限&quot;">​</a></h3><ul><li>你的公钥文件：<code>~/.ssh/id_rsa.pub</code>。</li><li>将<strong>公钥内容</strong>完整发送给运维人员。</li><li>运维会将其添加到服务器的 <code>~/.ssh/authorized_keys</code> 中，实现免密登录。</li></ul><blockquote><p>若希望自行测试，可用 <code>ssh-copy-id user@host</code> 命令（需服务器密码权限）。</p></blockquote><h3 id="_4-测试本地-ssh-连接" tabindex="-1">4. 测试本地 SSH 连接 <a class="header-anchor" href="#_4-测试本地-ssh-连接" aria-label="Permalink to &quot;4. 测试本地 SSH 连接&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.30</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.6.132</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>首次连接会提示确认服务器指纹，输入 <code>yes</code>。</li><li>若直接登录成功（或显示欢迎信息），说明免密配置生效。</li><li>若报错 <code>Permission denied (publickey)</code>，请检查： <ul><li>运维是否已正确添加公钥。</li><li>服务器上 <code>~/.ssh/authorized_keys</code> 权限是否为 <code>600</code>，<code>~/.ssh</code> 目录权限是否为 <code>700</code>。</li><li>本地私钥路径和权限是否正确</li></ul></li></ul><h3 id="_5-在-cursor-中远程连接" tabindex="-1">5. 在 Cursor 中远程连接 <a class="header-anchor" href="#_5-在-cursor-中远程连接" aria-label="Permalink to &quot;5. 在 Cursor 中远程连接&quot;">​</a></h3><ol><li>按 <code>F1</code> 打开命令面板。</li><li>输入 <code>Remote-SSH: Connect to Host...</code> 并回车。</li><li>选择你配置的 Host（如 <code>172.30.6.132</code> 或自定义别名）。</li><li>Cursor 会新开一个窗口，底部状态栏显示“正在连接…”。</li><li>连接成功后，左侧文件树即为远程服务器的目录，可以像本地一样编辑、运行终端命令。</li></ol><img width="1268" height="792" alt="Image" src="https://github.com/user-attachments/assets/bdd77456-a647-4615-b237-d714402a7804">`,21),t=[l];function r(n,d,c,h,p,u){return a(),e("div",null,t)}const g=s(o,[["render",r]]);export{m as __pageData,g as default};
